//===========================================================================//
// crate::gnuhurd::mig_user — hand-written MIG client stubs                  //
//                                                                           //
// Ports the "User" side generated by mig in C (fs.defs / io.defs). The      //
// server dispatch (_X*) already lives in Rust; these clients let the trivfs  //
// handlers forward to the realnode without linking libhurduser/libtrivfs.   //
//                                                                           //
// Wire layouts mirror fsUser.c / ioUser.c. All sizes and offsets are         //
// computed from size_of so the module works on i686 AND amd64. Type         //
// descriptors reuse the T_* constants from trivfs::io_server (cfg-aware).   //
//===========================================================================//

use std::ffi::{c_char, c_int};

use crate::gnumach::error::mach_error_t;
use crate::gnumach::kern_return::{kern_return_t, KERN_SUCCESS};
use crate::gnumach::message::{
    mach_msg, mach_msg_align, mach_msg_header_t, mach_msg_id_t, mach_msg_type_name_t,
    mach_msg_type_number_t, mach_msg_type_t, mach_msg_type_long_t, mach_msg_type_port_any,
    mach_msgh_bits, mach_msg_return_t, type_desc, type_desc_long, type_desc_long_ool, MACH_MSG_TYPE_CHAR,
    MACH_MSG_TYPE_COPY_SEND, MACH_MSG_TYPE_INTEGER_32, MACH_MSG_TYPE_MAKE_SEND_ONCE,
    MACH_MSG_TYPE_PORT_SEND,
    MACH_MSG_SUCCESS, MACH_MSGH_BITS_COMPLEX, MACH_MSG_OPTION_NONE,
    MACH_RCV_MSG, MACH_SEND_MSG, MACH_MSG_TIMEOUT_NONE,
};
use crate::gnumach::mig::{mig_reply_header_t, MIG_REPLY_MISMATCH, MIG_SERVER_DIED, MIG_TYPE_ERROR};
use crate::gnumach::notify::MACH_NOTIFY_SEND_ONCE;
use crate::gnumach::port::{
    mach_port_allocate, mach_port_deallocate, mach_port_t, MACH_PORT_NULL, MACH_PORT_RIGHT_RECEIVE,
};
use crate::gnumach::task::mach_task_self;
use crate::gnuhurd::io::{const_data_t, file_t, io_statbuf_t};
use crate::gnuhurd::types::fsys_t;
use crate::gnuhurd::trivfs::io_server::{
    T_INTEGER_32_1, T_INTEGER_32_2, T_TIMESPEC, T_STRING_C_1024,
};
use crate::gnuhurd::trivfs::times::{time_value_t, timespec_t};

// ── Shared helpers ──────────────────────────────────────────────────────────

fn alloc_reply_port() -> mach_port_t {
    let mut port = MACH_PORT_NULL;
    unsafe { mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &mut port); }
    port
}

fn dealloc_reply_port(port: mach_port_t) {
    unsafe { mach_port_deallocate(mach_task_self(), port); }
}

/// Offset of the RetCode field in any reply (header + RetCodeType).
const RETCODE: usize = size_of::<mach_msg_header_t>() + size_of::<mach_msg_type_t>();

/// MIG request header: COPY_SEND to target, MAKE_SEND_ONCE for the reply.
unsafe fn header_init(
    head: *mut mach_msg_header_t,
    size: usize,
    remote: mach_port_t,
    reply_port: mach_port_t,
    id: mach_msg_id_t,
) {
    (*head).msgh_bits = mach_msgh_bits(MACH_MSG_TYPE_COPY_SEND, MACH_MSG_TYPE_MAKE_SEND_ONCE);
    (*head).msgh_size = size as u32;
    (*head).msgh_remote_port = remote;
    (*head).msgh_local_port = reply_port;
    (*head).msgh_seqno = 0;
    (*head).msgh_id = id;
}

/// Write an already-packed type descriptor at dst; returns bytes consumed.
unsafe fn put_t(dst: *mut u8, t: mach_msg_type_t) -> usize {
    *(dst as *mut mach_msg_type_t) = t;
    size_of::<mach_msg_type_t>()
}

/// send + recv in one call, then verify the reply msgh_id.
unsafe fn mig_rpc(
    msg: *mut mach_msg_header_t,
    send_size: usize,
    recv_size: usize,
    reply_port: mach_port_t,
    reply_id: mach_msg_id_t,
) -> mach_msg_return_t {
    let r = mach_msg(
        msg,
        MACH_SEND_MSG | MACH_RCV_MSG | MACH_MSG_OPTION_NONE,
        send_size as u32,
        recv_size as u32,
        reply_port,
        MACH_MSG_TIMEOUT_NONE,
        MACH_PORT_NULL,
    );
    dealloc_reply_port(reply_port);
    if r != MACH_MSG_SUCCESS { return r; }
    if (*msg).msgh_id != reply_id {
        if (*msg).msgh_id == MACH_NOTIFY_SEND_ONCE { return MIG_SERVER_DIED; }
        return MIG_REPLY_MISMATCH;
    }
    MACH_MSG_SUCCESS
}

/// Check reply envelope per MIG TypeCheck. When `allow_complex` is set the
/// message may carry port rights (msgh_bits COMPLEX); otherwise a complex
/// reply is rejected. The size must be the full reply or a short error reply
/// (mig_reply_header_t, RetCode != 0).
unsafe fn check_envelope(
    rep: *const mach_msg_header_t,
    full_size: usize,
    retcode: kern_return_t,
    allow_complex: bool,
) -> mach_msg_return_t {
    if !allow_complex && (*rep).msgh_bits & MACH_MSGH_BITS_COMPLEX != 0 { return MIG_TYPE_ERROR; }
    let sz = (*rep).msgh_size as usize;
    if sz != full_size && !(sz == size_of::<mig_reply_header_t>() && retcode != KERN_SUCCESS) {
        return MIG_TYPE_ERROR;
    }
    MACH_MSG_SUCCESS
}

/// RetCodeType must be INTEGER_32,32,1.
unsafe fn check_retcode_type(rep: *const mach_msg_header_t) -> mach_msg_return_t {
    let t = (rep as *const u8).add(size_of::<mach_msg_header_t>()) as *const mach_msg_type_t;
    if *t != T_INTEGER_32_1 { return MIG_TYPE_ERROR; }
    MACH_MSG_SUCCESS
}

/// Common tail for simple (RetCode-only) replies.
unsafe fn simple_tail(
    msg: *const mach_msg_header_t,
    buf: *const u8,
) -> mach_error_t {
    let retcode = *(buf.add(RETCODE) as *const kern_return_t);
    let r = check_envelope(msg, size_of::<mig_reply_header_t>(), retcode, false);
    if r != MACH_MSG_SUCCESS { return r; }
    let r = check_retcode_type(msg);
    if r != MACH_MSG_SUCCESS { return r; }
    retcode
}

// ── fs.defs: file_* client stubs ───────────────────────────────────────────

/// file_chown (fs.defs). req 20001 / reply 20101.
pub unsafe fn file_chown(chown_file: file_t, new_owner: u32, new_group: u32) -> mach_error_t {
    let reply_port = alloc_reply_port();
    let fsz = size_of::<mach_msg_header_t>() + 2 * (size_of::<mach_msg_type_t>() + 4);
    let mut buf = vec![0u8; fsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, fsz, chown_file, reply_port, 20001);
    let mut o = size_of::<mach_msg_header_t>();
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut u32) = new_owner; o += 4;
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut u32) = new_group;
    let r = mig_rpc(msg, fsz, size_of::<mig_reply_header_t>(), reply_port, 20101);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

/// file_chmod (fs.defs). req 20003 / reply 20103.
pub unsafe fn file_chmod(chmod_file: file_t, new_mode: u32) -> mach_error_t {
    let reply_port = alloc_reply_port();
    let fsz = size_of::<mach_msg_header_t>() + size_of::<mach_msg_type_t>() + 4;
    let mut buf = vec![0u8; fsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, fsz, chmod_file, reply_port, 20003);
    let mut o = size_of::<mach_msg_header_t>();
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut u32) = new_mode;
    let r = mig_rpc(msg, fsz, size_of::<mig_reply_header_t>(), reply_port, 20103);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

/// file_utimes (fs.defs): time_value_t = 2×int32 (8B, fijo). req 20005 / 20105.
pub unsafe fn file_utimes(
    utimes_file: file_t,
    new_atime: time_value_t,
    new_mtime: time_value_t,
) -> mach_error_t {
    let reply_port = alloc_reply_port();
    let fsz = size_of::<mach_msg_header_t>() + 2 * (size_of::<mach_msg_type_t>() + size_of::<time_value_t>());
    let mut buf = vec![0u8; fsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, fsz, utimes_file, reply_port, 20005);
    let mut o = size_of::<mach_msg_header_t>();
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_2);          // time_value_t: 2×int32
    *(buf.as_mut_ptr().add(o) as *mut time_value_t) = new_atime; o += size_of::<time_value_t>();
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_2);
    *(buf.as_mut_ptr().add(o) as *mut time_value_t) = new_mtime;
    let r = mig_rpc(msg, fsz, size_of::<mig_reply_header_t>(), reply_port, 20105);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

/// file_utimens (fs.defs): timespec_t = 2×{long} (8B i386 / 16B amd64).
/// req 20035 / reply 20135.
pub unsafe fn file_utimens(
    utimes_file: file_t,
    new_atime: timespec_t,
    new_mtime: timespec_t,
) -> mach_error_t {
    let reply_port = alloc_reply_port();
    let fsz = size_of::<mach_msg_header_t>() + 2 * (size_of::<mach_msg_type_t>() + size_of::<timespec_t>());
    let mut buf = vec![0u8; fsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, fsz, utimes_file, reply_port, 20035);
    let mut o = size_of::<mach_msg_header_t>();
    o += put_t(buf.as_mut_ptr().add(o), T_TIMESPEC);               // 2×32 i386 / 2×64 amd64
    *(buf.as_mut_ptr().add(o) as *mut timespec_t) = new_atime; o += size_of::<timespec_t>();
    o += put_t(buf.as_mut_ptr().add(o), T_TIMESPEC);
    *(buf.as_mut_ptr().add(o) as *mut timespec_t) = new_mtime;
    let r = mig_rpc(msg, fsz, size_of::<mig_reply_header_t>(), reply_port, 20135);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

/// file_sync (fs.defs). req 20013 / reply 20113.
pub unsafe fn file_sync(file: file_t, wait: c_int, omit_metadata: c_int) -> mach_error_t {
    let reply_port = alloc_reply_port();
    let fsz = size_of::<mach_msg_header_t>() + 2 * (size_of::<mach_msg_type_t>() + 4);
    let mut buf = vec![0u8; fsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, fsz, file, reply_port, 20013);
    let mut o = size_of::<mach_msg_header_t>();
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut c_int) = wait; o += 4;
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut c_int) = omit_metadata;
    let r = mig_rpc(msg, fsz, size_of::<mig_reply_header_t>(), reply_port, 20113);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

/// file_check_access (fs.defs): Reply = RetCode + allowed. req 20009 / 20109.
pub unsafe fn file_check_access(file: file_t, allowed: *mut c_int) -> mach_error_t {
    // Reply: header + RetCodeType + RetCode + allowedType + allowed
    let rsz = size_of::<mach_msg_header_t>() + 2 * size_of::<mach_msg_type_t>()
        + size_of::<kern_return_t>() + size_of::<c_int>();
    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; rsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, size_of::<mach_msg_header_t>(), file, reply_port, 20009);
    let r = mig_rpc(msg, size_of::<mach_msg_header_t>(), rsz, reply_port, 20109);
    if r != MACH_MSG_SUCCESS { return r; }
    let retcode = *(buf.as_ptr().add(RETCODE) as *const kern_return_t);
    let r = check_envelope(msg, rsz, retcode, false);
    if r != MACH_MSG_SUCCESS { return r; }
    let r = check_retcode_type(msg);
    if r != MACH_MSG_SUCCESS { return r; }
    if retcode != KERN_SUCCESS { return retcode; }
    // allowedType must be INTEGER_32,32,1, then copy allowed.
    let allowed_type = RETCODE + size_of::<kern_return_t>();
    if *(buf.as_ptr().add(allowed_type) as *const mach_msg_type_t) != T_INTEGER_32_1 {
        return MIG_TYPE_ERROR;
    }
    if !allowed.is_null() {
        *allowed = *(buf.as_ptr().add(allowed_type + size_of::<mach_msg_type_t>()) as *const c_int);
    }
    retcode
}

/// file_set_translator (fs.defs): variable-size request with a `passive`
/// string, inline (<=2048B, aligned) or OOL. req 20027 / reply 20127.
pub unsafe fn file_set_translator(
    file: file_t,
    passive_flags: c_int,
    active_flags: c_int,
    oldtrans_flags: c_int,
    passive: const_data_t,
    passiveCnt: mach_msg_type_number_t,
    active: mach_port_t,
    activePoly: mach_msg_type_name_t,
) -> mach_error_t {
    const HDR: usize = size_of::<mach_msg_header_t>();
    const T: usize = size_of::<mach_msg_type_t>();
    // passive data starts after: header + 3×(type+int) + passiveType(long)
    const PASSIVE_OFF: usize = HDR + 3 * (T + 4) + size_of::<mach_msg_type_long_t>();
    // fixed base (message without passive bytes) = PASSIVE_OFF + activeType + active
    const BASE: usize = PASSIVE_OFF + T + size_of::<mach_port_t>();

    let reply_port = alloc_reply_port();
    let inline = passiveCnt <= 2048;
    let delta = if inline {
        mach_msg_align(passiveCnt as usize)
    } else {
        size_of::<*const c_char>()
    };
    let fsz = BASE + delta;
    let mut buf = vec![0u8; fsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;

    // A port right in `active` (and/or OOL data) makes the message complex.
    let msgh_simple = inline && !mach_msg_type_port_any(activePoly);
    (*msg).msgh_bits = if msgh_simple {
        mach_msgh_bits(MACH_MSG_TYPE_COPY_SEND, MACH_MSG_TYPE_MAKE_SEND_ONCE)
    } else {
        MACH_MSGH_BITS_COMPLEX | mach_msgh_bits(MACH_MSG_TYPE_COPY_SEND, MACH_MSG_TYPE_MAKE_SEND_ONCE)
    };
    (*msg).msgh_size = fsz as u32;
    (*msg).msgh_remote_port = file;
    (*msg).msgh_local_port = reply_port;
    (*msg).msgh_seqno = 0;
    (*msg).msgh_id = 20027;

    let mut o = HDR;
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut c_int) = passive_flags; o += 4;
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut c_int) = active_flags; o += 4;
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut c_int) = oldtrans_flags; o += 4;

    // passiveType: CHAR, 8 bits/element, longform; msgtl_number = passiveCnt.
    let pt = buf.as_mut_ptr().add(o) as *mut mach_msg_type_long_t;
    *pt = if inline {
        type_desc_long(MACH_MSG_TYPE_CHAR as u16, 8, passiveCnt)
    } else {
        type_desc_long_ool(MACH_MSG_TYPE_CHAR as u16, 8, passiveCnt)
    };

    let dst = buf.as_mut_ptr().add(PASSIVE_OFF);
    if inline {
        if passiveCnt > 0 && !passive.is_null() {
            std::ptr::copy_nonoverlapping(passive as *const u8, dst, passiveCnt as usize);
        }
    } else {
        *(dst as *mut *const c_char) = passive;
    }

    // activeType + active live right after the (aligned) passive area.
    let a = buf.as_mut_ptr().add(PASSIVE_OFF + delta);
    *(a as *mut mach_msg_type_t) = type_desc(activePoly, 32, 1);
    *(a.add(T) as *mut mach_port_t) = active;

    let r = mig_rpc(msg, fsz, size_of::<mig_reply_header_t>(), reply_port, 20127);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

// ── io.defs: io_* client stubs ─────────────────────────────────────────────

/// io_stat (io.defs): Reply carries an io_statbuf. req 21013 / reply 21113.
pub unsafe fn io_stat(stat_object: file_t, stat_info: *mut io_statbuf_t) -> mach_error_t {
    // Reply: header + RetCodeType + RetCode + stat_infoType + stat_info
    let rsz = size_of::<mach_msg_header_t>() + 2 * size_of::<mach_msg_type_t>()
        + size_of::<kern_return_t>() + size_of::<io_statbuf_t>();
    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; rsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, size_of::<mach_msg_header_t>(), stat_object, reply_port, 21013);
    let r = mig_rpc(msg, size_of::<mach_msg_header_t>(), rsz, reply_port, 21113);
    if r != MACH_MSG_SUCCESS { return r; }
    let retcode = *(buf.as_ptr().add(RETCODE) as *const kern_return_t);
    let r = check_envelope(msg, rsz, retcode, false);
    if r != MACH_MSG_SUCCESS { return r; }
    let r = check_retcode_type(msg);
    if r != MACH_MSG_SUCCESS { return r; }
    if retcode != KERN_SUCCESS { return retcode; }
    // stat_infoType must be INTEGER_32,32,32, then copy the io_statbuf.
    let stat_type = RETCODE + size_of::<kern_return_t>();
    if *(buf.as_ptr().add(stat_type) as *const mach_msg_type_t)
        != type_desc(MACH_MSG_TYPE_INTEGER_32, 32, 32) {
        return MIG_TYPE_ERROR;
    }
    if !stat_info.is_null() {
        *stat_info = *(buf.as_ptr().add(stat_type + size_of::<mach_msg_type_t>()) as *const io_statbuf_t);
    }
    retcode
}

/// io_revoke (io.defs): Reply = RetCode only. req 21030 / reply 21130.
pub unsafe fn io_revoke(revoke_object: file_t) -> mach_error_t {
    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; size_of::<mig_reply_header_t>()];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, size_of::<mach_msg_header_t>(), revoke_object, reply_port, 21030);
    let r = mig_rpc(msg, size_of::<mach_msg_header_t>(), size_of::<mig_reply_header_t>(), reply_port, 21130);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

