/// io_pathconf (io.defs): Reply = RetCode + value. req 21028 / reply 21128.
pub unsafe fn io_pathconf(io_object: file_t, name: c_int, value: *mut c_int) -> mach_error_t {
    // Reply: header + RetCodeType + RetCode + valueType + value
    let rsz = size_of::<mach_msg_header_t>() + 2 * size_of::<mach_msg_type_t>()
        + size_of::<kern_return_t>() + size_of::<c_int>();
    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; rsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, 32, io_object, reply_port, 21028);
    let mut o = size_of::<mach_msg_header_t>();
    o += put_t(buf.as_mut_ptr().add(o), T_INTEGER_32_1);
    *(buf.as_mut_ptr().add(o) as *mut c_int) = name;
    let r = mig_rpc(msg, 32, rsz, reply_port, 21128);
    if r != MACH_MSG_SUCCESS { return r; }
    let retcode = *(buf.as_ptr().add(RETCODE) as *const kern_return_t);
    let r = check_envelope(msg, rsz, retcode, false);
    if r != MACH_MSG_SUCCESS { return r; }
    let r = check_retcode_type(msg);
    if r != MACH_MSG_SUCCESS { return r; }
    if retcode != KERN_SUCCESS { return retcode; }
    // valueType must be INTEGER_32,32,1, then copy value.
    let value_type = RETCODE + size_of::<kern_return_t>();
    if *(buf.as_ptr().add(value_type) as *const mach_msg_type_t) != T_INTEGER_32_1 {
        return MIG_TYPE_ERROR;
    }
    if !value.is_null() {
        *value = *(buf.as_ptr().add(value_type + size_of::<mach_msg_type_t>()) as *const c_int);
    }
    retcode
}

/// io_duplicate (io.defs): Reply = RetCode + newport (port). req 21016 / 21116.
pub unsafe fn io_duplicate(io_object: file_t, newport: *mut mach_port_t) -> mach_error_t {
    // Reply: header + RetCodeType + RetCode + newportType + newport
    let rsz = size_of::<mach_msg_header_t>() + 2 * size_of::<mach_msg_type_t>()
        + size_of::<kern_return_t>() + size_of::<mach_port_t>();
    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; rsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, size_of::<mach_msg_header_t>(), io_object, reply_port, 21016);
    let r = mig_rpc(msg, size_of::<mach_msg_header_t>(), rsz, reply_port, 21116);
    if r != MACH_MSG_SUCCESS { return r; }
    let retcode = *(buf.as_ptr().add(RETCODE) as *const kern_return_t);
    let r = check_envelope(msg, rsz, retcode, true);
    if r != MACH_MSG_SUCCESS { return r; }
    let r = check_retcode_type(msg);
    if r != MACH_MSG_SUCCESS { return r; }
    if retcode != KERN_SUCCESS { return retcode; }
    // newportType must be PORT_SEND,32,1, then read newport.
    let port_type = RETCODE + size_of::<kern_return_t>();
    if *(buf.as_ptr().add(port_type) as *const mach_msg_type_t) != type_desc(MACH_MSG_TYPE_PORT_SEND, 32, 1) {
        return MIG_TYPE_ERROR;
    }
    if !newport.is_null() {
        *newport = *(buf.as_ptr().add(port_type + size_of::<mach_msg_type_t>()) as *const mach_port_t);
    }
    retcode
}

/// io_restrict_auth (io.defs): Request carries uids/gids idarrays, Reply =
/// RetCode + new_object (port). req 21015 / reply 21115.
pub unsafe fn io_restrict_auth(
    io_object: file_t,
    new_object: *mut mach_port_t,
    uids: *const u32,
    uidsCnt: mach_msg_type_number_t,
    gids: *const u32,
    gidsCnt: mach_msg_type_number_t,
) -> mach_error_t {
    const HDR: usize = size_of::<mach_msg_header_t>();
    const LT: usize = size_of::<mach_msg_type_long_t>();
    const UID_SZ: usize = size_of::<u32>();

    // uids (long) + inline data + gids (long) + inline data
    let uid_len = mach_msg_align(uidsCnt as usize * UID_SZ);
    let gid_len = mach_msg_align(gidsCnt as usize * UID_SZ);
    let fsz = HDR + LT + uid_len + LT + gid_len;

    // Reply: header + RetCodeType + RetCode + new_objectType + new_object
    let rsz = size_of::<mach_msg_header_t>() + 2 * size_of::<mach_msg_type_t>()
        + size_of::<kern_return_t>() + size_of::<mach_port_t>();

    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; fsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, fsz, io_object, reply_port, 21015);

    let mut o = HDR;
    let ut = buf.as_mut_ptr().add(o) as *mut mach_msg_type_long_t;
    *ut = type_desc_long(MACH_MSG_TYPE_INTEGER_32 as u16, 32, uidsCnt);
    o += LT;
    if uidsCnt > 0 && !uids.is_null() {
        std::ptr::copy_nonoverlapping(uids as *const u8, buf.as_mut_ptr().add(o), uidsCnt as usize * UID_SZ);
    }
    o += uid_len;
    let gt = buf.as_mut_ptr().add(o) as *mut mach_msg_type_long_t;
    *gt = type_desc_long(MACH_MSG_TYPE_INTEGER_32 as u16, 32, gidsCnt);
    o += LT;
    if gidsCnt > 0 && !gids.is_null() {
        std::ptr::copy_nonoverlapping(gids as *const u8, buf.as_mut_ptr().add(o), gidsCnt as usize * UID_SZ);
    }

    let r = mig_rpc(msg, fsz, rsz, reply_port, 21115);
    if r != MACH_MSG_SUCCESS { return r; }
    let retcode = *(buf.as_ptr().add(RETCODE) as *const kern_return_t);
    let r = check_envelope(msg, rsz, retcode, true);
    if r != MACH_MSG_SUCCESS { return r; }
    let r = check_retcode_type(msg);
    if r != MACH_MSG_SUCCESS { return r; }
    if retcode != KERN_SUCCESS { return retcode; }
    // new_objectType must be PORT_SEND,32,1, then read new_object.
    let port_type = RETCODE + size_of::<kern_return_t>();
    if *(buf.as_ptr().add(port_type) as *const mach_msg_type_t) != type_desc(MACH_MSG_TYPE_PORT_SEND, 32, 1) {
        return MIG_TYPE_ERROR;
    }
    if !new_object.is_null() {
        *new_object = *(buf.as_ptr().add(port_type + size_of::<mach_msg_type_t>()) as *const mach_port_t);
    }
    retcode
}

/// auth_server_authenticate (auth.defs): request = handle + rendezvous port +
/// newport port (COPY_SEND); reply = RetCode + euids/auids/egids/agids arrays
/// (idarray_t, inline <=512 or OOL). req 25004 / reply 25104.
///
/// On success the 4 out arrays are copied into the caller buffers (capped at
/// 512 elements each). OOL arrays are deallocated after copying.
pub unsafe fn auth_server_authenticate(
    handle: mach_port_t,
    rendezvous: mach_port_t,
    newport: mach_port_t,
    euids: *mut *const u32,
    euidsCnt: *mut mach_msg_type_number_t,
    auids: *mut *const u32,
    auidsCnt: *mut mach_msg_type_number_t,
    egids: *mut *const u32,
    egidsCnt: *mut mach_msg_type_number_t,
    agids: *mut *const u32,
    agidsCnt: *mut mach_msg_type_number_t,
) -> mach_error_t {
    const HDR: usize = size_of::<mach_msg_header_t>();
    const T: usize = size_of::<mach_msg_type_t>();
    const LT: usize = size_of::<mach_msg_type_long_t>();
    const UID_SZ: usize = size_of::<u32>();

    // Request: header + rendezvousType + rendezvous + newportType + newport
    let fsz = HDR + T + size_of::<mach_port_t>() + T + size_of::<mach_port_t>();
    // Reply: header + RetCodeType + RetCode + 4×(long + 512-element array)
    const CAP: usize = 512;
    let rsz = HDR + 2 * T + 4 * (LT + CAP * UID_SZ);

    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; rsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, fsz, handle, reply_port, 25004);

    let mut o = HDR;
    o += put_t(buf.as_mut_ptr().add(o), type_desc(MACH_MSG_TYPE_PORT_SEND, 32, 1));
    *(buf.as_mut_ptr().add(o) as *mut mach_port_t) = rendezvous; o += size_of::<mach_port_t>();
    o += put_t(buf.as_mut_ptr().add(o), type_desc(MACH_MSG_TYPE_PORT_SEND, 32, 1));
    *(buf.as_mut_ptr().add(o) as *mut mach_port_t) = newport;

    let r = mig_rpc(msg, fsz, rsz, reply_port, 25104);
    if r != MACH_MSG_SUCCESS { return r; }
    let retcode = *(buf.as_ptr().add(RETCODE) as *const kern_return_t);
    let r = check_envelope(msg, rsz, retcode, false);
    if r != MACH_MSG_SUCCESS { return r; }
    let r = check_retcode_type(msg);
    if r != MACH_MSG_SUCCESS { return r; }
    if retcode != KERN_SUCCESS { return retcode; }

    // 4 idarray_t fields; each is a mach_msg_type_long_t followed by data.
    let mut off = RETCODE + size_of::<kern_return_t>();
    let copy_array = |off: &mut usize, dst: *mut *const u32, dst_cnt: *mut mach_msg_type_number_t| {
        let lt = *(buf.as_ptr().add(*off) as *const mach_msg_type_long_t);
        *off += LT;
        let n = lt.number() as usize;
        let data_ptr = buf.as_ptr().add(*off);
        if !dst.is_null() && !dst_cnt.is_null() {
            if n <= CAP {
                *dst_cnt = n as u32;
                *dst = data_ptr as *const u32;
                *off += mach_msg_align(n * UID_SZ);
            } else {
                // OOL pointer
                let p = *(data_ptr as *const *const u32);
                *dst_cnt = n as u32;
                *dst = p;
                *off += size_of::<*const u32>();
            }
        } else {
            *off += if lt.is_inline() { mach_msg_align(n * UID_SZ) } else { size_of::<*const u32>() };
        }
    };
    copy_array(&mut off, euids, euidsCnt);
    copy_array(&mut off, auids, auidsCnt);
    copy_array(&mut off, egids, egidsCnt);
    copy_array(&mut off, agids, agidsCnt);

    retcode
}

// ── fsys.defs: fsys_* client stubs ─────────────────────────────────────────
//
// These operate on the fsys (control) port, obtained via file_getcontrol.
// Their defaults return EOPNOTSUPP; the smokes validate the wire only.

/// fsys_forward (fsys.defs): hand the request to another translator.
/// req 22008 / reply 22108. argv is CHAR/8 longform (inline <=2048B, else OOL).
pub unsafe fn fsys_forward(
    server: fsys_t,
    requestor: mach_port_t,
    requestorPoly: mach_msg_type_name_t,
    argv: const_data_t,
    argvCnt: mach_msg_type_number_t,
) -> mach_error_t {
    const HDR: usize = size_of::<mach_msg_header_t>();
    const T: usize = size_of::<mach_msg_type_t>();
    const LT: usize = size_of::<mach_msg_type_long_t>();
    // requestor(4) + argvType(LT) at base; argv data follows.
    const BASE: usize = HDR + T + size_of::<mach_port_t>() + LT;

    let reply_port = alloc_reply_port();
    let inline = argvCnt <= 2048;
    let delta = if inline {
        mach_msg_align(argvCnt as usize)
    } else {
        size_of::<*const c_char>()
    };
    let fsz = BASE + delta;
    let mut buf = vec![0u8; fsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;

    // A port right in `requestor` (and/or OOL argv) makes the message complex,
    // as in the C client (msgh_simple = FALSE when requestorPoly is port-any).
    let complex = mach_msg_type_port_any(requestorPoly) || !inline;
    (*msg).msgh_bits = if complex {
        MACH_MSGH_BITS_COMPLEX | mach_msgh_bits(MACH_MSG_TYPE_COPY_SEND, MACH_MSG_TYPE_MAKE_SEND_ONCE)
    } else {
        mach_msgh_bits(MACH_MSG_TYPE_COPY_SEND, MACH_MSG_TYPE_MAKE_SEND_ONCE)
    };
    (*msg).msgh_size = fsz as u32;
    (*msg).msgh_remote_port = server;
    (*msg).msgh_local_port = reply_port;
    (*msg).msgh_seqno = 0;
    (*msg).msgh_id = 22008;

    let mut o = HDR;
    // requestor is polymorphic: pass the caller's type (PORT_SEND → T_PORT_SEND_1).
    *(buf.as_mut_ptr().add(o) as *mut mach_msg_type_t) = type_desc(requestorPoly, 32, 1);
    o += T;
    *(buf.as_mut_ptr().add(o) as *mut mach_port_t) = requestor;
    o += size_of::<mach_port_t>();
    *(buf.as_mut_ptr().add(o) as *mut mach_msg_type_long_t) = if inline {
        type_desc_long(MACH_MSG_TYPE_CHAR as u16, 8, argvCnt)
    } else {
        type_desc_long_ool(MACH_MSG_TYPE_CHAR as u16, 8, argvCnt)
    };
    o += LT;
    let dst = buf.as_mut_ptr().add(o);
    if inline {
        if argvCnt > 0 && !argv.is_null() {
            std::ptr::copy_nonoverlapping(argv as *const u8, dst, argvCnt as usize);
        }
    } else {
        *(dst as *mut *const c_char) = argv;
    }

    let r = mig_rpc(msg, fsz, size_of::<mig_reply_header_t>(), reply_port, 22108);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

/// fsys_get_children (fsys.defs): return active child translators.
/// req 22010 / reply 22110. Reply carries names (CHAR/8, up to 2048 inline or
/// OOL) and controls (portarray, up to 512). Only the return code is validated
/// (the default is EOPNOTSUPP); the success OOL path is not parsed.
pub unsafe fn fsys_get_children(
    server: fsys_t,
    _names: *mut *mut c_char,
    _namesCnt: *mut mach_msg_type_number_t,
    _controls: *mut *mut mach_port_t,
    _controlsCnt: *mut mach_msg_type_number_t,
) -> mach_error_t {
    const HDR: usize = size_of::<mach_msg_header_t>();
    const T: usize = size_of::<mach_msg_type_t>();
    const LT: usize = size_of::<mach_msg_type_long_t>();
    // Buffer that can hold the full inline reply (names 2048 + controls 512×port)
    // plus the headers; computed from the types, not a hardcoded byte count.
    const NAMES_CAP: usize = 2048;    // fsys.defs: names limit
    const CONTROLS_CAP: usize = 512;  // fsys.defs: controls limit
    let rsz = HDR + 2 * T + size_of::<kern_return_t>()
        + 2 * LT + NAMES_CAP + CONTROLS_CAP * size_of::<mach_port_t>();

    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; rsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, HDR, server, reply_port, 22010);
    let r = mig_rpc(msg, HDR, buf.len(), reply_port, 22110);
    if r != MACH_MSG_SUCCESS { return r; }
    simple_tail(msg, buf.as_ptr())
}

/// fsys_get_source (fsys.defs): return the source of the translator.
/// req 22011 / reply 22111. Reply carries a string_t (STRING_C/1024).
pub unsafe fn fsys_get_source(server: fsys_t, source: *mut c_char) -> mach_error_t {
    const HDR: usize = size_of::<mach_msg_header_t>();
    const T: usize = size_of::<mach_msg_type_t>();
    // string_t = char[1024] (fsys.defs): size from the C type, not a literal.
    const STRING_T: usize = size_of::<[c_char; 1024]>();
    let rsz = HDR + T + size_of::<kern_return_t>() + T + STRING_T;

    let reply_port = alloc_reply_port();
    let mut buf = vec![0u8; rsz];
    let msg = buf.as_mut_ptr() as *mut mach_msg_header_t;
    header_init(msg, HDR, server, reply_port, 22011);
    let r = mig_rpc(msg, HDR, rsz, reply_port, 22111);
    if r != MACH_MSG_SUCCESS { return r; }
    let retcode = *(buf.as_ptr().add(RETCODE) as *const kern_return_t);
    let r = check_envelope(msg, rsz, retcode, false);
    if r != MACH_MSG_SUCCESS { return r; }
    let r = check_retcode_type(msg);
    if r != MACH_MSG_SUCCESS { return r; }
    if retcode != KERN_SUCCESS { return retcode; }
    // sourceType + source (STRING_C/1024) right after RetCode.
    let st = RETCODE + size_of::<kern_return_t>();
    if *(buf.as_ptr().add(st) as *const mach_msg_type_t) != T_STRING_C_1024 {
        return MIG_TYPE_ERROR;
    }
    if !source.is_null() {
        std::ptr::copy_nonoverlapping(
            buf.as_ptr().add(st + T),
            source as *mut u8,
            STRING_T,
        );
    }
    retcode
}